#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The Jetson wizard (#39): the Jetson Orin Nano Super, from a board this laptop reaches over SSH to the Jetson
# column's results, with no agent in the loop.
#
#   bash jetson/wizard.sh [plan]      from Git Bash on the laptop; jetson/provision.sh first, on a blank SD card
#                                     plan: default plans/jetson.json; a copy under a new name is a new session
#
# It probes the board (#11: GO, BLOCKED or CUT), sets the highest power mode with jetson_clocks, installs PLATFORMS.md's
# pins (jetson/install.sh), copies the files, builds the 8 TensorRT engines on the board (jetson/export.sh), runs
# plans/jetson.json through the session runner, and brings the results home to score them. Every stage finds what is
# already done, so run it again at any time. The engine builds and the session run on the board under nohup: closing
# the wizard or losing SSH stops neither. Rehearsal hooks, as in pi/wizard.sh: WIZ_SSH stands in for ssh,
# WIZ_DRY_RUN=1 adds the runner's --dry-run, WIZ_RESULTS is where the results come home to (default study/), and
# WIZ_PROBE_OUT is where the probe's report is saved (default study/verification/jetson_probe.txt).

run_wizard() {

TOTAL_STAGES=9

STUDY="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$STUDY"
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE="$STUDY/jetson/.env"
PLAN="${1:-plans/jetson.json}"
SSH_BIN="${WIZ_SSH:-ssh}"
DRY="${WIZ_DRY_RUN:-}"
RESULTS="${WIZ_RESULTS:-$STUDY}"
J_DIR="uav/study"     # on the board, under its home
J_VENV="uav-venv"     # jetson/install.sh's venv, under the board's home
J_CKPT="uav-ckpt"     # the checkpoints, under the board's home: studyexport.py names a run after its folder
RUNS=(yolo11s-640-s0 yolo26s-640-s0 yolo11s-960-s0 yolo26s-960-s0)
PROBE_OUT="${WIZ_PROBE_OUT:-verification/jetson_probe.txt}"
OUT="bench/jetson/$(basename "$PLAN" .json)"   # the runner's default --out
LPY=python3
for p in .venv/Scripts/python.exe .venv/bin/python; do [[ -x "$p" ]] && { LPY="$STUDY/$p"; break; }; done

die() { warn "$1"; exit 1; }
good() { say "${GREEN}✓${RESET} $1"; }
LOST="lost the connection to the board (what runs there under nohup keeps running): run the wizard again"
lpy() { "$LPY" "$@" | tr -d '\r'; }
[[ -f "$PLAN" ]] || die "no plan at study/$PLAN"
# Every path the plan needs on the board: the images and the reference export are copied; the engines are built there
NEEDS=(); ENGINES=(); REF=""
while IFS= read -r p; do
  if [[ "$p" == */tensorrt-* ]]; then ENGINES+=("$p"); else NEEDS+=("$p"); fi
  [[ "$p" == */onnxruntime-fp32 ]] && REF="$p"
done < <(lpy scripts/studysession.py "$PLAN" --needs)
(( ${#ENGINES[@]} == 8 )) || die "$PLAN should name the 8 engines jetson/export.sh builds, and names ${#ENGINES[@]}"
[[ -n "$REF" ]] || die "the session runner names no ONNX Runtime FP32 reference: see scripts/studysession.py REFERENCE"
NEEDS+=(datasets/VisDrone/images/val datasets/VisDrone/labels/val)   # INT8 calibration, on all 548 val images
SMALL=(scripts/studybench.py scripts/studysession.py scripts/studyexport.py scripts/studyenv.py scripts/studycap.py
       scripts/jetson_probe.py cfg/invariants.yaml "$PLAN" jetson/install.sh jetson/export.sh)

# jet CMD runs CMD on the board with no stdin; jet_in keeps stdin (tar); jet_t gives it a terminal, for sudo's password;
# jet_sh runs the script on stdin there, in the study folder, with PLAN, OUT and PY (the venv's python) set, and its
# own arguments as $1, $2...
SSH_OPTS=(-o ConnectTimeout=10 -o ServerAliveInterval=30)
jet()    { "$SSH_BIN" -n "${SSH_OPTS[@]}" "$J_USER@$J_HOST" "$@"; }
jet_in() { "$SSH_BIN" "${SSH_OPTS[@]}" "$J_USER@$J_HOST" "$@"; }
jet_t()  { "$SSH_BIN" -t "${SSH_OPTS[@]}" "$J_USER@$J_HOST" "$@"; }
jet_sh() {
  { printf 'PLAN=%q OUT=%q PY="$HOME/%s/bin/python"\n' "$PLAN" "$OUT" "$J_VENV"
    printf 'mkdir -p "$HOME/%s" && cd "$HOME/%s" || exit 1\n' "$J_DIR" "$J_DIR"
    cat; } | jet_in "bash -s -- $(printf '%q ' "$@")" | tr -d '\r'
}
next() { pause "Press Enter for the next stage"; }
key_ok() { "$SSH_BIN" -n -o BatchMode=yes -o ConnectTimeout=10 "$J_USER@$J_HOST" true 2>/dev/null; }
# wait_back: after a reboot, wait up to 5 minutes for SSH to answer again
wait_back() {
  say "Waiting for the board to come back (up to 5 minutes)..."
  sleep 20
  for _ in $(seq 28); do
    if key_ok; then good "it is back"; return 0; fi
    printf '.'; sleep 10
  done
  printf '\n'
  die "the board did not come back over SSH: check its power and network, then run the wizard again"
}
# The same one-hash-over-every-file-under-a-path, on the laptop (tree_hash) and on the board (TREE_HASH, for jet_sh)
TREE_HASH='LC_ALL=C find "$1" -type f -print0 | LC_ALL=C sort -z | xargs -0 sha256sum | sed -E "s/^([0-9a-f]{64}) [ *]/\1  /" | sha256sum | cut -c1-64'
tree_hash() { bash -c "$TREE_HASH" _ "$1"; }
jet_hash()  { printf '[ -e "$1" ] || { echo missing; exit 0; }\n%s\n' "$TREE_HASH" | jet_sh "$1"; }
ckpt_hash() { sha256sum < "$J_CKPT_LOCAL/$1/best.pt" | cut -c1-64; }
jet_ckpt_hash() { jet "f=\"\$HOME/$J_CKPT/$1/best.pt\"; if [ -f \"\$f\" ]; then sha256sum < \"\$f\" | cut -c1-64; else echo missing; fi" | tr -d '\r'; }
free_gb() {
  if command -v powershell.exe >/dev/null 2>&1; then
    powershell.exe -NoProfile -Command "[math]::Round((Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory/1MB,1)" | tr -d '\r'
  else awk '/MemAvailable/ {printf "%.1f\n", $2 / 1048576}' /proc/meminfo; fi
}
# board_state: the power mode, the highest mode and jetson_clocks, from jetson_probe.board_state(), as key=value lines
board_state() { jet_sh <<'EOF'
python3 - <<'PY'
import sys
sys.path.insert(0, "scripts")
import jetson_probe as j
b = j.board_state()
m, h = b["nvpmodel_mode"] or ("", ""), b["highest_mode"] or ("", "")
if not m[0] and m[0] != 0:  # nvpmodel -q gave nothing: nvpmodel's status file says "pmode:0002 ..."
    import re
    s = re.search(r"pmode:(\d+)", b["nvpmodel_status"] or "")
    if s:
        m = (int(s[1]), dict(b["nvpmodel_modes"]).get(int(s[1]), "?"))
print(f"mode={m[0]}\nmode_name={m[1]}\nhigh={h[0]}\nhigh_name={h[1]}\nclocks={b['jetson_clocks']}")
PY
EOF
}
bs() { printf '%s\n' "$STATE" | sed -n "s/^$1=//p"; }
# power_ok: the board is in its highest mode with jetson_clocks on; otherwise it offers the fixes (sudo, over SSH)
power_ok() {
  STATE=$(board_state) || die "$LOST"
  [[ -n "$(bs high)" ]] || die "the board lists no nvpmodel modes (/etc/nvpmodel.conf): is this a Jetson on JetPack 6?"
  if [[ "$(bs mode)" != "$(bs high)" ]]; then
    warn "the power mode is $(bs mode_name) ($(bs mode)); the study runs in the highest, $(bs high_name) ($(bs high))."
    note "sudo asks for the board's password. If nvpmodel asks to reboot, answer YES: the wizard waits for the board."
    confirm "Set $(bs high_name) now?" || return 1
    jet_t "sudo nvpmodel -m $(bs high)" || true
    sleep 5   # if it is rebooting, let SSH go down first
    key_ok || wait_back
    STATE=$(board_state) || die "$LOST"
    [[ "$(bs mode)" == "$(bs high)" ]] || { warn "the mode is still $(bs mode_name) ($(bs mode))."; return 1; }
  fi
  good "power mode: $(bs mode_name) ($(bs mode)), the highest"
  if [[ "$(bs clocks)" != True ]]; then
    warn "jetson_clocks is not on ($(bs clocks)). It pins the clocks at their maximum, and does not survive a reboot."
    confirm "Turn it on now (sudo jetson_clocks)?" || return 1
    jet_t "sudo jetson_clocks" || true
    STATE=$(board_state) || die "$LOST"
    [[ "$(bs clocks)" == True ]] || { warn "jetson_clocks still reads $(bs clocks)."; return 1; }
  fi
  good "jetson_clocks: on"
}
# The engines' status: how many of the 8 have a manifest; and the build's state on the board
engines_built() {
  jet_sh "${ENGINES[@]}" <<'EOF'
n=0; for e in "$@"; do [ -f "$e/manifest.json" ] && n=$((n + 1)); done; echo "$n"
EOF
}
export_status() { jet_sh <<'EOF'
pid=$(cat exports/jetson-export.pid 2>/dev/null)
if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null && tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -q export.sh; then
  echo running
elif [ -f exports/jetson-export.log ]; then
  echo stopped
else
  echo new
fi
EOF
}
start_export() { jet_sh "${1:-}" <<'EOF'
mkdir -p exports
S=; command -v setsid >/dev/null && S=setsid
nohup $S bash jetson/export.sh $1 >> exports/jetson-export.log 2>&1 < /dev/null &
echo $! > exports/jetson-export.pid
EOF
}

banner "Jetson Orin Nano Super: the Jetson column (plans/jetson.json)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "What you need ready"
say "This wizard takes the Jetson from the probe to the results: 8 TensorRT engines (YOLO11s and YOLO26s, FP16 and"
say "INT8, 640 and 960), each timed on all 1,610 test-dev images, latency only (#11)."
printf '\n'
J_CKPT_LOCAL=$(_existing J_CKPT_LOCAL || true)
[[ -n "$J_CKPT_LOCAL" ]] || J_CKPT_LOCAL="$HOME/uav-yolo-checkpoints"
ask J_CKPT_LOCAL "The folder on this laptop with the trained checkpoints [$J_CKPT_LOCAL]:" || true
[[ -n "$J_CKPT_LOCAL" ]] || J_CKPT_LOCAL="$HOME/uav-yolo-checkpoints"
J_CKPT_LOCAL="${J_CKPT_LOCAL%/}"
[[ -d "$J_CKPT_LOCAL" ]] || die "no folder $J_CKPT_LOCAL: run the wizard again with the right one"
write_env J_CKPT_LOCAL "$J_CKPT_LOCAL"
for r in "${RUNS[@]}"; do
  pt="$J_CKPT_LOCAL/$r/best.pt"
  if [[ -f "$pt" ]]; then good "$r/best.pt"; continue; fi
  # A browser download of a Kaggle output names the checkpoint best.pt.zip. A .pt is itself a zip (torch's format,
  # with <name>/data.pkl inside), so such a file is the checkpoint under another name: copied, never unzipped.
  if [[ -f "$pt.zip" ]] && lpy -c 'import sys, zipfile; sys.exit(not any(n.endswith("/data.pkl") for n in zipfile.ZipFile(sys.argv[1]).namelist()))' "$pt.zip"; then
    say "$r has best.pt.zip: a torch checkpoint under a .zip name (do not unzip it)."
    confirm "Copy it to $r/best.pt?" || die "the board needs $r/best.pt: run the wizard again"
    cp "$pt.zip" "$pt"
    good "$r/best.pt (copied from best.pt.zip)"
    continue
  fi
  die "no checkpoint for $r in $J_CKPT_LOCAL. The YOLO26s ones come from Vidhyarth's Kaggle output (#37)."
done
count() { find "$1" -maxdepth 1 -type f | wc -l; }
for d in images/val:548 labels/val:548 images/test:1610; do
  p="datasets/VisDrone/${d%:*}"
  [[ -d "$p" ]] || die "missing on this laptop: study/$p"
  n=$(count "$p")
  if [[ "$n" == "${d#*:}" ]]; then good "$p: $n files"; else warn "$p has $n files, and the study's has ${d#*:}."; fi
done
for p in "${NEEDS[@]}"; do [[ -e "$p" ]] || die "missing on this laptop: study/$p (make it with scripts/studyexport.py)"; done
good "the drift reference: $REF"
printf '\n'
say "On the board's side, have these ready:"
step "The Orin Nano Super on its 19 V supply, set up by jetson/provision.sh: on this laptop's network, SSH with a key."
step "Internet on the board: the install downloads about 3 GB (torch, cuDSS, the pins)."
step "The board's password, for sudo: the power mode, jetson_clocks and the install's apt steps."
note "The engine builds and the session take hours and run on the board: you can close the wizard and come back."
confirm "Is all of that ready?" || { say "Run the wizard again when it is."; exit 0; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Connect to the board"
ask J_HOST "The board's host name or IP (jetson/provision.sh saved it):"
ask J_USER "The user on the board:"
write_env J_HOST "$J_HOST"
write_env J_USER "$J_USER"
if key_ok; then
  good "SSH with a key works."
else
  warn "SSH without a password does not work yet."
  if [[ ! -f "$HOME/.ssh/id_ed25519.pub" ]] && confirm "Make an SSH key on this laptop (~/.ssh/id_ed25519, no passphrase)?"; then
    ssh-keygen -t ed25519 -N "" -f "$HOME/.ssh/id_ed25519"
  fi
  say "Copying the key to the board: type the board's password when ssh asks."
  ssh-copy-id -i "$HOME/.ssh/id_ed25519.pub" "$J_USER@$J_HOST" || true
  key_ok || die "still no SSH: check the host and user, and that the board is on this network; then run the wizard again"
  good "SSH with a key works now."
fi
MODEL=$(jet "tr -d '\\0' 2>/dev/null < /proc/device-tree/model; echo; uname -m" | tr -d '\r' | paste -sd ' ' -) || die "$LOST"
say "The board says: $MODEL"
if [[ "$MODEL" != *"Orin Nano"* ]]; then
  warn "this is not a Jetson Orin Nano, and the study's Jetson column is for one (#11)."
  confirm "Go on anyway?" || exit 1
fi
next

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Probe the board"
tar -cf - "${SMALL[@]}" | jet_in "mkdir -p \"\$HOME/$J_DIR\" && tar -xf - -C \"\$HOME/$J_DIR\"" || die "$LOST"
say "Copied the scripts, the plan and the board's two helpers (small: always copied)."
while :; do
  say "Running scripts/jetson_probe.py on the board (read-only, about 30 s)..."
  PROBE=$(jet_sh <<'EOF'
python3 scripts/jetson_probe.py
EOF
) || die "$LOST"
  mkdir -p "$(dirname "$PROBE_OUT")"
  { printf '# jetson_probe.py on %s@%s, %s (jetson/wizard.sh)\n' "$J_USER" "$J_HOST" "$(date -Is)"; printf '%s\n' "$PROBE"; } > "$PROBE_OUT"
  printf '%s\n' "$PROBE" | grep -E '^(board|memory|disk|L4T|JetPack|TensorRT|CUDA|Python|nvpmodel |reach|VERDICT|  BLOCKER|  note|run mode)' \
    | cut -c1-150 | sed 's/^/  /'
  note "The whole report is in study/$PROBE_OUT."
  VERDICT=$(printf '%s\n' "$PROBE" | sed -n 's/^VERDICT *//p')
  case "$VERDICT" in
    GO) good "GO: an Orin Nano on JetPack 6, nothing in the way."; break ;;
    CUT*) die "the probe says CUT: the Jetson is listed as future work (#11). Paste study/$PROBE_OUT into #11." ;;
    BLOCKED) ;;
    *) die "the probe gave no verdict: see study/$PROBE_OUT" ;;
  esac
  warn "BLOCKED: fix each BLOCKER above, then the probe runs again."
  if printf '%s\n' "$PROBE" | grep -q 'BLOCKER.*TensorRT'; then
    PKG=nvidia-jetpack
    printf '%s\n' "$PROBE" | grep -q 'BLOCKER.*python3-libnvinfer' && PKG=python3-libnvinfer
    if confirm "Install $PKG on the board now (sudo apt; nvidia-jetpack is about 3 GB)?"; then
      jet_t "sudo apt-get update && sudo apt-get install -y $PKG" || warn "the apt install failed: see above"
    fi
  fi
  if printf '%s\n' "$PROBE" | grep -q 'BLOCKER.*PyPI'; then
    note "pip cannot reach PyPI from the board. Join a network with plain internet (this laptop's Mobile Hotspot),"
    note "or set the lab's proxy on the board (export https_proxy=...)."
  fi
  confirm "Probe again?" || exit 1
done
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if confirm "Post the probe's report to #11 on GitHub (PLATFORMS.md step 1 asks for it)?"; then
    { printf 'Probe of the Jetson Orin Nano Super, from `jetson/wizard.sh`:\n\n```\n'; printf '%s\n' "$PROBE"; printf '```\n'; } \
      | gh issue comment 11 --body-file - && good "posted to #11" || warn "the post failed: paste study/$PROBE_OUT into #11 by hand"
  fi
else
  SKIPPED+=("paste study/$PROBE_OUT into #11 (gh is not ready here)")
fi
next

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Power mode and clocks"
say "Every run is in the board's highest nvpmodel mode with jetson_clocks on (#11), and records both."
power_ok || { warn "the board is not in the study's power state."; confirm "Go on anyway (the runs record the state they ran in)?" || exit 1; }
DESK=$(jet "systemctl is-active display-manager 2>/dev/null; systemctl get-default" | tr -d '\r' | paste -sd ' ' -) || die "$LOST"
if [[ "$DESK" == active* ]]; then
  say "The desktop is running (display-manager $DESK)."
  note "Closing it frees about 1 GB for the INT8 builds at 960 and keeps the board quiet while it is timed (#8)."
  note "It stays closed until the next reboot. The screen goes to a text console; SSH is not affected."
  if confirm "Close the desktop for this boot (sudo systemctl isolate multi-user.target)?"; then
    jet_t "sudo systemctl isolate multi-user.target" || warn "it did not close: see above"
  fi
else
  good "no desktop running ($DESK)"
fi
next

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Install"
CHECK=$(jet "bash \"\$HOME/$J_DIR/jetson/install.sh\" --check; echo rc=\$?" | tr -d '\r') || die "$LOST"
if [[ "$CHECK" == *"rc=0"* ]]; then
  good "the install is complete (~/$J_VENV):"
  printf '%s\n' "$CHECK" | grep '^have' | sed 's/^/    /'
else
  say "The install is not complete:"
  printf '%s\n' "$CHECK" | grep -E '^(have|want|no venv)' | cut -c1-160 | sed 's/^/    /'
  say "jetson/install.sh makes ~/$J_VENV and installs PLATFORMS.md's Jetson pins: numpy 1.26.4, the Jetson torch 2.10.0"
  say "and torchvision 0.25.0 wheels, cuDSS 0.7.1 (apt), then ultralytics 8.4.149, onnx, onnxslim, opencv-python and"
  say "onnxruntime (the CPU build, for the drift reference). Steps already done are skipped."
  note "sudo asks for the board's password. It needs internet on the board: about 3 GB, 15-30 minutes."
  confirm "Install now?" || exit 1
  jet_t "bash \"\$HOME/$J_DIR/jetson/install.sh\"" || die "the install failed: see its output above, fix it, and run the wizard again"
  good "the install is complete"
fi
next

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Copy the images, the reference export and the checkpoints"
FREE=$(jet "df -Pk \"\$HOME\" | awk 'NR == 2 {printf \"%.0f\\n\", \$4 * 1024}'" | tr -d '\r') || die "$LOST"
FREE=${FREE:-0}
declare -A HASH=()
TO_COPY=()
for p in "${NEEDS[@]}"; do
  HASH[$p]=$(tree_hash "$p")
  there=$(jet_hash "$p") || die "$LOST"
  if [[ "$there" == "${HASH[$p]}" ]]; then say "already there: $p"; else TO_COPY+=("$p"); fi
done
CK_COPY=()
for r in "${RUNS[@]}"; do
  HASH[ckpt/$r]=$(ckpt_hash "$r")
  if [[ "$(jet_ckpt_hash "$r")" == "${HASH[ckpt/$r]}" ]]; then say "already there: ~/$J_CKPT/$r/best.pt"; else CK_COPY+=("$r"); fi
done
if (( ${#TO_COPY[@]} + ${#CK_COPY[@]} )); then
  NEED=$(( $(du -scb ${TO_COPY[@]+"${TO_COPY[@]}"} /dev/null | tail -n1 | cut -f1) + ${#CK_COPY[@]} * (20 << 20) + (3 << 30) ))
  say "To copy: ${TO_COPY[*]-} ${CK_COPY[*]+checkpoints: ${CK_COPY[*]}}"
  say "With the engines and the results, that needs up to $(( NEED >> 20 )) MB on the card; $(( FREE >> 20 )) MB are free."
  (( FREE >= NEED )) || warn "not enough space on the card."
  note "A path that differs at all is copied again whole, so an interrupted copy starts over."
  confirm "Copy now?" || exit 0
fi
for p in ${TO_COPY[@]+"${TO_COPY[@]}"}; do
  say "copying $p ($(du -sh "$p" | cut -f1))..."
  tar -cf - "$p" | jet_in "cd \"\$HOME/$J_DIR\" && rm -rf $(printf '%q' "$p") && tar -xf -" || die "the copy of $p failed: run the wizard again"
  [[ "$(jet_hash "$p")" == "${HASH[$p]}" ]] || die "the copy of $p on the board differs from the laptop's: run the wizard again"
  say "  copied and checked."
done
for r in ${CK_COPY[@]+"${CK_COPY[@]}"}; do
  say "copying the checkpoint $r..."
  tar -cf - -C "$J_CKPT_LOCAL" "$r/best.pt" | jet_in "mkdir -p \"\$HOME/$J_CKPT\" && tar -xf - -C \"\$HOME/$J_CKPT\"" \
    || die "the copy of $r failed: run the wizard again"
  [[ "$(jet_ckpt_hash "$r")" == "${HASH[ckpt/$r]}" ]] || die "the checkpoint $r on the board differs from the laptop's: run the wizard again"
  say "  copied and checked."
done
good "everything the engines and the session need is on the board"
next

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Build the 8 TensorRT engines on the board"
say "An engine runs only on the GPU and TensorRT that built it, so the board builds its own (PLATFORMS.md step 5)."
note "Each build takes minutes; an INT8 one first calibrates on the 548 val images. YOLO11s FP16 at 640 goes first:"
note "it is the first TensorRT engine this study has built anywhere, so watch it. INT8 at 960 goes last."
show_export() { jet_sh <<'EOF'
grep -E '^=== |^\[tensorrt-|FAILED|Error|Killed' exports/jetson-export.log 2>/dev/null | tail -n 14 | cut -c1-150 | sed 's/^/  /'
EOF
}
WS=""
while :; do
  BUILT=$(engines_built) || die "$LOST"
  ST=$(export_status) || die "$LOST"
  if [[ "$BUILT" == 8 ]]; then good "all 8 engines are built"; break; fi
  case "$ST" in
    running) ;;
    new|stopped)
      if [[ "$ST" == stopped ]]; then
        warn "$BUILT of 8 engines are built, and the build has stopped. Its log:"
        show_export
        if jet_sh <<'EOF' | grep -q yes
tail -n 60 exports/jetson-export.log 2>/dev/null | grep -qiE 'out of memory|Killed|std::bad_alloc|OutOfMemory' && echo yes
EOF
        then
          warn "a build ran out of memory. A 1 GiB TensorRT workspace often fixes it (the manifest records it)."
          note "Stage 4 can close the desktop, which frees about 1 GB more."
          confirm "Build the missing engines again with --workspace 1?" && WS=1
        fi
        confirm "Build the missing engines now${WS:+ (workspace ${WS} GiB)}?" || exit 1
      else
        say "No engine is built yet: $BUILT of 8."
        confirm "Start the builds on the board now?" || exit 0
      fi
      power_ok || warn "the builds record the power state they ran in."
      start_export "$WS"; sleep 5 ;;
  esac
  ST=$(export_status) || die "$LOST"
  while [[ "$ST" == running ]]; do
    BUILT=$(engines_built) || die "$LOST"
    _clear
    printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "Building the engines: $BUILT of 8" "$RESET"
    show_export
    printf '\n'
    note "It refreshes every 30 s. Type l and Enter to leave it building and close the wizard; Ctrl-C does the same."
    rc=0; read -r -t 30 key || rc=$?
    if (( rc == 0 )); then
      [[ "$key" == l ]] && { say "It keeps building on the board. Run the wizard again to come back: bash jetson/wizard.sh"; exit 0; }
    elif (( rc <= 128 )); then
      sleep 30   # no terminal input left (a rehearsal): wait anyway
    fi
    ST=$(export_status) || die "$LOST"
  done
done
next

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Run the session on the board"
session_status() { jet_sh <<'EOF'
pid=$(cat "$OUT/runner.pid" 2>/dev/null)
if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null && tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -q studysession; then
  echo running
elif [ -f "$OUT/session.json" ]; then
  s=$("$PY" -c 'import json, sys; print(json.load(open(sys.argv[1])).get("status"))' "$OUT/session.json")
  [ "$s" = running ] && s=stopped   # its runner is gone (a power cut, a kill): the same command resumes it
  echo "$s"
else
  echo new
fi
EOF
}
show_progress() { jet_sh <<'EOF'
[ -f "$OUT/summary.csv" ] && "$PY" - "$OUT/summary.csv" <<'PROGRESS'
import csv, sys
with open(sys.argv[1], newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
for r in [{"cell": "cell", "outcome": "outcome", "latency_ms": "latency_ms", "throttle": "throttle"}, *rows]:
    print(f"  {r['cell']:<42} {r['outcome']:<14} {r['latency_ms']:<16} {r['throttle']}")
PROGRESS
echo; tail -n 8 "$OUT/session.log" 2>/dev/null | cut -c1-160
EOF
}
start_session() { jet_sh "$DRY" <<'EOF'
mkdir -p "$OUT"
args=(); [ -n "$1" ] && args+=(--dry-run)
S=; command -v setsid >/dev/null && S=setsid
nohup $S "$PY" -u scripts/studysession.py "$PLAN" --out "$OUT" "${args[@]}" >> "$OUT/runner.out" 2>&1 < /dev/null &
echo $! > "$OUT/runner.pid"
EOF
}
say "plans/jetson.json: the 8 engines in a shuffled order, between two runs of the drift reference (YOLO11s, ONNX"
say "Runtime FP32 on the CPU, 200 images), with the start gate and the re-runs of #8."
ST=$(session_status) || die "$LOST"
case "$ST" in
  complete) say "This session is already complete on the board." ;;
  running)  say "This session is running on the board." ;;
  *)        if [[ "$ST" == new ]]; then say "No session of this plan on the board yet."
            else say "The session on the board is $ST: starting it again resumes it (finished runs are kept)."; fi
            power_ok || { warn "the board is not in the study's power state."; confirm "Run anyway (the runs record it)?" || exit 1; }
            note "Leave the board alone while it runs: no desktop, no other work, so the timings are clean."
            confirm "$([[ "$ST" == new ]] && echo Start || echo Resume) it now?" || exit 0
            start_session; sleep 3 ;;
esac
while :; do
  ST=$(session_status) || die "$LOST"
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "Run the session on the board: $ST" "$RESET"
  show_progress
  [[ "$ST" == running ]] || break
  printf '\n'
  note "It refreshes every 30 s. Type l and Enter to leave it running and close the wizard; Ctrl-C does the same."
  rc=0; read -r -t 30 key || rc=$?
  if (( rc == 0 )); then
    [[ "$key" == l ]] && { say "It keeps running on the board. Run the wizard again to come back: bash jetson/wizard.sh"; exit 0; }
  elif (( rc <= 128 )); then
    sleep 30   # no terminal input left (a rehearsal): wait anyway
  fi
done
if [[ "$ST" != complete ]]; then
  warn "the session stopped as $ST. The runner's last words:"
  jet_sh <<'EOF' | sed 's/^/    /'
tail -n 15 "$OUT/runner.out" 2>/dev/null
EOF
  die "fix what it says, then run the wizard again: it resumes the session"
fi
good "The session is complete."
next

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Copy the results home, and score them"
mkdir -p "$RESULTS"
confirm "Copy the results and the engines' manifests home, and score them, now?" || { say "Run the wizard again to do it later."; exit 0; }
# The runs and the manifests, not the engines: they run only on this board
jet "cd \"\$HOME/$J_DIR\" && tar -cf - $(printf '%q' "$OUT") $(printf '%q/manifest.json ' "${ENGINES[@]}")" | tar -xf - -C "$RESULTS" \
  || die "$LOST"
say "Copied to $RESULTS/$OUT, with the 8 engines' manifests under exports/"
SUMMARY="$RESULTS/$OUT/summary.csv"
command -v cygpath >/dev/null 2>&1 && SUMMARY=$(cygpath -m "$SUMMARY")
INFO=$(lpy - "$SUMMARY" <<'PY'
import csv, sys
sys.path.insert(0, "scripts")
import studysession as s
with open(sys.argv[1], newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
cells = [r for r in rows if r["cell"] not in s.DRIFT_UNITS]
print("drift=" + (rows[0]["drift"] if rows else "unknown"))
for r in cells:
    if r["run_dir"]:
        print("run=" + r["run_dir"])
for r in [dict(zip(rows[0], rows[0])), *rows] if rows else []:
    print("row=" + "\t".join(r[k] for k in ("cell", "precision", "images", "outcome", "latency_ms", "throttle", "drift")))
PY
)
RUN_DIRS=()
while IFS= read -r r; do RUN_DIRS+=("$r"); done < <(printf '%s\n' "$INFO" | sed -n 's/^run=//p')
DRIFT=$(printf '%s\n' "$INFO" | sed -n 's/^drift=//p')
SCORE_CMD=("$LPY" scripts/studyscore.py)
for r in ${RUN_DIRS[@]+"${RUN_DIRS[@]}"}; do
  d="$RESULTS/$OUT/$r"
  command -v cygpath >/dev/null 2>&1 && d=$(cygpath -m "$d")
  SCORE_CMD+=("$d")
done
SCORED=""
(( ${#RUN_DIRS[@]} )) || { warn "no cell finished, so there is nothing to score."; SCORED=none; }
note "Accuracy is not required for the Jetson column (#11), but it costs nothing."
while (( ${#RUN_DIRS[@]} )); do
  GB=$(free_gb)
  if awk -v f="$GB" 'BEGIN {exit !(f >= 3)}'; then
    say "Scoring ${#RUN_DIRS[@]} run(s) (free RAM ${GB} GB)..."
    if "${SCORE_CMD[@]}"; then SCORED=yes; else warn "scoring failed: see above"; fi
    break
  fi
  warn "only ${GB} GB of RAM is free, and scoring wants 3 GB. Close Chrome or Edge, then press Enter to check again."
  printf '  %ss and Enter skips the scoring:%s ' "$DIM" "$RESET"
  read -r key || key=s
  [[ "$key" == s ]] && break
done
[[ -n "$SCORED" ]] || SKIPPED+=("score later, from study/: ${SCORE_CMD[*]}")
printf '\n'
say "The session's summary (latency in ms):"
printf '%s\n' "$INFO" | sed -n 's/^row=//p' | column -t -s $'\t' | sed 's/^/    /'
if [[ "$DRIFT" == re-run || "$DRIFT" == unknown ]]; then
  warn "the drift check says $DRIFT: this session's latencies are not trusted, and its cells run again (#8)."
  warn "Copy the plan to a new name, e.g. ${PLAN%.json}-2.json, and run the wizard with it: a new name is a new session."
  SKIPPED+=("run this session's cells again (drift $DRIFT): cp $PLAN ${PLAN%.json}-2.json; bash jetson/wizard.sh ${PLAN%.json}-2.json")
fi
printf '\n'
say "For INVARIANTS.md §1.3's Jetson row (its TBDs must be filled before any number is reported):"
grep -E '^(board|memory|L4T|JetPack|TensorRT|CUDA|cuDNN) ' "$PROBE_OUT" 2>/dev/null | cut -c1-150 | sed 's/^/    /'
MAN="$RESULTS/${ENGINES[0]}/manifest.json"
command -v cygpath >/dev/null 2>&1 && MAN=$(cygpath -m "$MAN")
lpy - "$MAN" <<'PY' | sed 's/^/    /' || true
import json, sys
m = json.load(open(sys.argv[1], encoding="utf-8"))
e = m.get("engine") or {}
print("engine        TensorRT %s, GPU %s, torch CUDA %s, cuDNN %s" % (e.get("tensorrt"), e.get("gpu"), e.get("torch_cuda"), e.get("cudnn")))
print("power         nvpmodel %s, jetson_clocks %s" % (e.get("nvpmodel_mode"), e.get("jetson_clocks")))
print("toolchain     " + ", ".join(f"{k} {v}" for k, v in (m.get("toolchain") or {}).items() if v))
PY
SKIPPED+=("fill the Jetson row of INVARIANTS.md §1.3 from the lines above (study/$PROBE_OUT has the whole probe)")
next

finish
}

run_wizard "$@"; exit
